package net.zartra.gui;
import java.util.*;
final class ActionCodec {private ActionCodec(){}static List<Map<String,Object>> writeAll(List<ActionEntry> list){List<Map<String,Object>> out=new ArrayList<Map<String,Object>>();for(ActionEntry a:list)out.add(write(a));return out;}static Map<String,Object> write(ActionEntry a){Map<String,Object> z=new LinkedHashMap<String,Object>();z.put("id",a.id);z.put("type",a.type);z.put("value",a.value);z.put("order",a.order);z.put("delay",a.delay);z.put("chance",a.chance);z.put("enabled",a.enabled);z.put("stop-on-failure",a.stopOnFailure);z.put("condition-mode",a.conditionMode.name());z.put("condition-failure-message",a.conditionFailureMessage);z.put("success-actions",writeAll(a.successActions));z.put("failure-actions",writeAll(a.failureActions));List<Map<String,Object>> c=new ArrayList<Map<String,Object>>();for(ConditionEntry x:a.conditions){Map<String,Object> m=new LinkedHashMap<String,Object>();m.put("id",x.id);m.put("type",x.type.name());m.put("value",x.value);m.put("order",x.order);m.put("enabled",x.enabled);m.put("inverted",x.inverted);m.put("failure-message",x.failureMessage);c.add(m);}z.put("conditions",c);return z;}static List<ActionEntry> readAll(Object o){List<ActionEntry> out=new ArrayList<ActionEntry>();if(o instanceof List)for(Object x:(List)o)if(x instanceof Map){ActionEntry a=read((Map)x);if(a!=null)out.add(a);}return out;}static ActionEntry read(Map raw){try{ActionEntry a=new ActionEntry();a.id=raw.get("id")==null?a.id:String.valueOf(raw.get("id"));a.type=String.valueOf(raw.get("type"));if(MenuAction.parse(a.type+":")==null)return null;a.value=raw.get("value")==null?"":String.valueOf(raw.get("value"));a.order=num(raw.get("order"),0);a.delay=num(raw.get("delay"),0);a.chance=dbl(raw.get("chance"),100);a.enabled=bool(raw.get("enabled"),true);a.stopOnFailure=bool(raw.get("stop-on-failure"),false);try{a.conditionMode=ConditionSet.Mode.valueOf(String.valueOf(raw.get("condition-mode")));}catch(Exception ignored){}a.conditionFailureMessage=raw.get("condition-failure-message")==null?"":String.valueOf(raw.get("condition-failure-message"));for(Object co:raw.get("conditions") instanceof List?(List)raw.get("conditions"):Collections.emptyList())if(co instanceof Map)try{Map cm=(Map)co;ConditionEntry c=new ConditionEntry(ConditionEntry.Type.valueOf(String.valueOf(cm.get("type"))),String.valueOf(cm.get("value")));c.id=cm.get("id")==null?c.id:String.valueOf(cm.get("id"));c.order=num(cm.get("order"),a.conditions.size());c.enabled=bool(cm.get("enabled"),true);c.inverted=bool(cm.get("inverted"),false);c.failureMessage=cm.get("failure-message")==null?"":String.valueOf(cm.get("failure-message"));a.conditions.add(c);}catch(Exception ignored){}a.successActions.addAll(readAll(raw.get("success-actions")));a.failureActions.addAll(readAll(raw.get("failure-actions")));return ActionValidator.chance(a.chance)&&ActionValidator.delay(a.delay)?a:null;}catch(Exception e){return null;}}private static int num(Object x,int d){try{return Integer.parseInt(String.valueOf(x));}catch(Exception e){return d;}}private static double dbl(Object x,double d){try{return Double.parseDouble(String.valueOf(x));}catch(Exception e){return d;}}private static boolean bool(Object x,boolean d){return x==null?d:Boolean.parseBoolean(String.valueOf(x));}}